import assert from "node:assert/strict";
import { readFile, stat } from "node:fs/promises";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

const file = "plugin/server.mjs";
const setupFile = "plugin/setup.mjs";
const workerFile = "plugin/update-worker.mjs";
const skillFile = "plugin/skills/bitrix24-read/SKILL.md";
const source = await readFile(file, "utf8");
const setupSource = await readFile(setupFile, "utf8");
const info = await stat(file);
const setupInfo = await stat(setupFile);
const workerSource = await readFile(workerFile, "utf8");
const workerInfo = await stat(workerFile);
const skillSource = await readFile(skillFile, "utf8");

if (info.size > 2_000_000) throw new Error(`bundle is too large: ${info.size} bytes`);
if (!source.includes("Generated by npm run build"))
  throw new Error("bundle does not contain the generated marker");
if (source.includes("BITRIX24_WEBHOOK_BASE_URL=https://"))
  throw new Error("bundle appears to contain a configured webhook URL");
if (setupInfo.size > 100_000)
  throw new Error(`setup bundle is too large: ${setupInfo.size} bytes`);
if (!setupSource.includes("Generated by npm run build"))
  throw new Error("setup bundle does not contain the generated marker");
if (setupSource.includes("BITRIX24_WEBHOOK_BASE_URL=https://"))
  throw new Error("setup bundle appears to contain a configured webhook URL");
if (workerInfo.size > 100_000)
  throw new Error(`update worker bundle is too large: ${workerInfo.size} bytes`);
if (!workerSource.includes("Generated by npm run build"))
  throw new Error("update worker bundle does not contain the generated marker");
if (workerSource.includes("BITRIX24_WEBHOOK_BASE_URL=https://"))
  throw new Error("update worker bundle appears to contain a configured webhook URL");
for (const expected of [
  "ask_question",
  "**⬆️ Обновить** / **Позже**",
  'optionId: "update"',
  "allowFreeform",
  "approvalToken",
  "Never print or quote `approvalToken`",
]) {
  if (!skillSource.includes(expected))
    throw new Error(`skill is missing button-update contract: ${expected}`);
}

const transport = new StdioClientTransport({
  command: process.execPath,
  args: [file],
  env: {
    PATH: process.env.PATH ?? "",
    BITRIX24_WEBHOOK_BASE_URL:
      "https://portal.example.invalid/rest/123/test",
    PLUGIN_ROOT: "/tmp/iva-bundle-smoke/data/custom/plugins/bitrix24-read",
    PLUGIN_DATA: "/tmp/iva-bundle-smoke/data/plugin-data/bitrix24-read",
  },
  stderr: "pipe",
});
const client = new Client({ name: "bundle-smoke", version: "1.0.0" });
try {
  await client.connect(transport);
  const { tools } = await client.listTools();
  assert.deepEqual(
    tools.map(({ name }) => name).sort(),
    [
      "bitrix24_connection_check",
      "bitrix24_get_task",
      "bitrix24_list_tasks",
      "bitrix24_task_fields",
      "bitrix24_task_history",
      "iva_bitrix24_update_apply",
      "iva_bitrix24_update_check",
      "iva_bitrix24_update_status",
    ],
  );
} finally {
  await client.close();
}

console.log(
  `bundles ok: MCP ${info.size} bytes, setup ${setupInfo.size} bytes, updater ${workerInfo.size} bytes; stdio MCP smoke passed`,
);
